"""assets/ai/agentic_pipeline/ops_schema.json (a real per-op JSON Schema for all 25 ops, generated by
tools/gen_agentic_pipeline_ops_schema.py from the live `_STEP_MODELS`) must never silently drift from the real
models it was generated from -- the exact gap that let schema.json's `steps` field describe 18 ops (stale since the
8-ops era) while the real component already supported 25. Regenerate with:

    python3 tools/gen_agentic_pipeline_ops_schema.py --fix
"""
import importlib.util
import json
import pathlib
import sys

HERE = pathlib.Path(__file__).resolve()
REPO_ROOT = HERE.parents[4]
TOOLS_DIR = REPO_ROOT / "tools"
OPS_SCHEMA_PATH = REPO_ROOT / "assets" / "ai" / "agentic_pipeline" / "ops_schema.json"


def _load_gen_tool():
    spec = importlib.util.spec_from_file_location("gen_agentic_pipeline_ops_schema", TOOLS_DIR / "gen_agentic_pipeline_ops_schema.py")
    mod = importlib.util.module_from_spec(spec)
    sys.modules[spec.name] = mod
    spec.loader.exec_module(mod)
    return mod


def test_ops_schema_json_matches_the_live_step_models(mod):
    gen = _load_gen_tool()
    fresh = gen.build_ops_schema(mod)
    fresh_text = json.dumps(fresh, indent=2, sort_keys=True) + "\n"
    current_text = OPS_SCHEMA_PATH.read_text()
    assert current_text == fresh_text, (
        "ops_schema.json is stale vs. the live _STEP_MODELS -- run: "
        "python3 tools/gen_agentic_pipeline_ops_schema.py --fix"
    )


def test_ops_schema_json_covers_every_op_with_a_real_schema(mod):
    data = json.loads(OPS_SCHEMA_PATH.read_text())
    assert set(data) == set(mod._STEP_MODELS)
    for op, entry in data.items():
        assert entry["schema"].get("properties"), f"{op} has no real schema properties"
